Q: Could not resolve placeholder &#39;server.port&#39; in value &quot;${server.port}&quot; A: <p>I had the same issue, I solved this simply by adding the <strong>server.port</strong> property to <strong>application.properties</strong></p>
<p><strong>MultiplicationController.java</strong></p>
<pre><code>@Slf4j
@RestController
@RequestMapping(&quot;/multiplications&quot;)
@CrossOrigin(origins = &quot;http://localhost:9090&quot;)
final class MultiplicationController {

    private final MultiplicationService multiplicationService;

    private final int serverPort;

    @Autowired
    public MultiplicationController(final MultiplicationService multiplicationService,
            @Value(&quot;${server.port}&quot;) int serverPort) {
        this.multiplicationService = multiplicationService;
        this.serverPort = serverPort;
    }

    @GetMapping(&quot;/random&quot;)
    public Multiplication getRandomMultiplication() {
        log.info(&quot;Generating a random multiplication from server @ {}&quot;, serverPort);
        return multiplicationService.createRandomMultiplication();
    }
}
</code></pre>
<p><strong>application.properties</strong></p>
<pre><code>server.port=8080
</code></pre>

Q: How to change Number Picker center text color in Android A: <p>The easiest way to do this</p>

<pre><code>setNumberPickerTextColor(mNumberPicker);

public void setNumberPickerTextColor(NumberPicker numberPicker){
    int color=Color.parseColor("#333333");

    final int count = numberPicker.getChildCount();
    for(int i = 0; i &lt; count; i++){
        View child = numberPicker.getChildAt(i);
        if(child instanceof EditText){
            try{
                Field selectorWheelPaintField = numberPicker.getClass().getDeclaredField("mSelectorWheelPaint");
                selectorWheelPaintField.setAccessible(true);
                ((Paint)selectorWheelPaintField.get(numberPicker)).setColor(color);
                ((EditText)child).setTextColor(color);
                numberPicker.invalidate();
            }
            catch(NoSuchFieldException e){
                Log.e("setNumberPickerColor1", ""+e);
            }
            catch(IllegalAccessException e){
                Log.e("setNumberPickerColor2", ""+e);
            }
            catch(IllegalArgumentException e){
                Log.e("setNumberPickerColor3", ""+e);
            }
        }
    }
}
</code></pre>

Q: How to get all music files stored in internal storage and external storage in android using MediaStore? A: <pre><code>object MusicFetcher {

    fun getAllMusic(context: Context): ArrayList&lt;MusicModel&gt; {
        val musicList = ArrayList&lt;MusicModel&gt;()

        val projection = arrayOf(
            MediaStore.Audio.Media._ID,
            MediaStore.Audio.Media.TITLE,
            MediaStore.Audio.Media.ARTIST,
            MediaStore.Audio.Media.DURATION,
            MediaStore.Audio.Media.DATA,
            MediaStore.Audio.Media.DATE_ADDED
        )

        val selection = &quot;${MediaStore.Audio.Media.IS_MUSIC} != 0&quot;
        val sortOrder = MediaStore.Audio.Media.DATE_ADDED + &quot; DESC&quot;

        val cursor = context.contentResolver.query(
            MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,
            projection,
            selection,
            null,
            sortOrder
        )

        cursor?.use {
            val idCol = it.getColumnIndexOrThrow(MediaStore.Audio.Media._ID)
            val titleCol = it.getColumnIndexOrThrow(MediaStore.Audio.Media.TITLE)
            val artistCol = it.getColumnIndexOrThrow(MediaStore.Audio.Media.ARTIST)
            val durationCol = it.getColumnIndexOrThrow(MediaStore.Audio.Media.DURATION)
            val pathCol = it.getColumnIndexOrThrow(MediaStore.Audio.Media.DATA)
            val dateAddedCol = it.getColumnIndexOrThrow(MediaStore.Audio.Media.DATE_ADDED)

            while (it.moveToNext()) {

                val songId = it.getLong(idCol)
                val title = it.getString(titleCol) ?: &quot;Unknown Title&quot;
                val artist = it.getString(artistCol) ?: &quot;Unknown Artist&quot;
                val duration = it.getLong(durationCol)
                val path = it.getString(pathCol)
                val dateAdded = it.getLong(dateAddedCol)

                val songUri: Uri = ContentUris.withAppendedId(
                    MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,
                    songId
                )

                musicList.add(
                    MusicModel(
                        id = songId,
                        title = title,
                        artistName = artist,
                        duration = duration,
                        path = path,
                        songContentUri = songUri.toString(),
                        dateAdded = dateAdded
                    )
                )
            }
        }

        return musicList
    }
}
</code></pre>
